package com.sigtm.backend.controller;
import com.sigtm.backend.model.SeguimientoCompra; import com.sigtm.backend.service.SeguimientoCompraService; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/compras/{orderId}/seguimiento") @RequiredArgsConstructor public class SeguimientoCompraController {private final SeguimientoCompraService service; @GetMapping @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<SeguimientoCompra> obtener(@PathVariable Long orderId){return ResponseEntity.ok(service.obtener(orderId));} @PutMapping @PreAuthorize("hasAuthority('COMPRAS:EDITAR')") public ResponseEntity<SeguimientoCompra> actualizar(@PathVariable Long orderId,@RequestBody SeguimientoCompra s){return ResponseEntity.ok(service.actualizar(orderId,s));}}
